def parse_log(text):
    import json
    parsed_logs = []
    lines = text.splitlines()
    for line in lines:
        try:
            if line.strip():  # Skip blank lines
                parsed_logs.append(json.loads(line))
        except json.JSONDecodeError:
            continue  # Skip malformed lines
    return parsed_logs

